const sql=require("mssql"),{getSourceConfig:getSourceConfig}=require("../db.helper"),mssqlConfig=getSourceConfig(),CLINIC_ID=1;class DataMigrator{constructor(){this.mssqlPool=null,this.stats={users:0,services:0,patients:0,appointments:0,items:0,examinations:0}}async connect(){this.mssqlPool=await sql.connect(mssqlConfig)}async disconnect(){this.mssqlPool&&await this.mssqlPool.close()}async extractUsers(){const e=await this.mssqlPool.request().query("\n            SELECT \n                TAKIPNO,\n                GIRISKODU,\n                ISIMSOYISIM,\n                GOREVNO,\n                UZMANLIK,\n                IPTAL\n            FROM KULLANICILAR\n            WHERE TAKIPNO > 0\n            ORDER BY TAKIPNO\n        "),n=await this.getSpecialtyMap(),i=e.recordset.map((e=>({legacy_id:e.TAKIPNO,username:(e.GIRISKODU||`user_${e.TAKIPNO}`).toLowerCase().substring(0,50),name:e.ISIMSOYISIM||`Kullanıcı ${e.TAKIPNO}`,role:this.mapUserRole(e.GOREVNO),specialty:this.mapSpecialty(e.UZMANLIK,n),is_active:e.IPTAL?0:1})));return this.stats.users=i.length,i}mapUserRole(e){switch(e){case 2:return"doctor";case 16:case 11:return"secretary";default:return"admin"}}async getSpecialtyMap(){const e=await this.mssqlPool.request().query("\n            SELECT TAKIPNO, UZMANLIK FROM LST_UZMANLIKDALLARI\n        "),n={};return e.recordset.forEach((e=>{n[e.TAKIPNO]=e.UZMANLIK})),n}mapSpecialty(e,n){if(!e)return null;const i=n[e];if(!i)return null;const t=i.toLowerCase();return t.includes("iç hastalıkları")||t.includes("dahiliye")?"INTERNAL_MEDICINE":t.includes("diyetisyen")||t.includes("beslenme")?"DIETITIAN":t.includes("kardiyoloji")?"CARDIOLOGY":t.includes("kulak")||t.includes("kbb")?"ENT":t.includes("göz")?"OPHTHALMOLOGY":t.includes("ortopedi")?"ORTHOPEDICS":t.includes("dermatoloji")||t.includes("cildiye")?"DERMATOLOGY":t.includes("nöroloji")?"NEUROLOGY":t.includes("psikiyatri")||t.includes("psikolog")?"PSYCHIATRY":t.includes("kadın")||t.includes("jinekoloji")?"GYNECOLOGY":t.includes("çocuk")||t.includes("pediatri")?"PEDIATRICS":t.includes("üroloji")?"UROLOGY":t.includes("cerrahi")?"GENERAL_SURGERY":t.includes("göğüs")?"PULMONOLOGY":t.includes("endokrin")?"ENDOCRINOLOGY":t.includes("enfeksiyon")?"INFECTIOUS_DISEASES":t.includes("acil")?"EMERGENCY":null}async extractServices(){const e=(await this.mssqlPool.request().query("\n            SELECT \n                KOD,\n                ACIKLAMA,\n                FIYAT,\n                BUTFIYATI,\n                IPTAL\n            FROM TETKIK\n            WHERE ACIKLAMA IS NOT NULL AND ACIKLAMA != ''\n            ORDER BY KOD\n        ")).recordset.map((e=>({legacy_code:String(e.KOD),name:e.ACIKLAMA,price:e.FIYAT||e.BUTFIYATI||0,is_active:e.IPTAL?0:1})));return this.stats.services=e.length,e}async extractPatients(){const e=(await this.mssqlPool.request().query("\n            SELECT \n                P.HASTANO,\n                P.AD, P.SOYAD, P.KIMLIKNO,\n                EV_TELEFON, EV_MOBIL, EV_EMAIL,\n                DGMTRH, DOGUMYERI, CINSIYET, KANGRUBU,\n                EV_ADRES1, EV_ADRES2, EV_ADRES_SEMT, EV_ADRES_ILCE, EV_ADRES_IL,\n                BABAADI, ANNEADI, MESLEK, NK_UYRUGU, NOTLAR,\n                ILACALERJISI, MADDEALERJISI, TIBBIUYARI,\n                ARSIVNO, AILENO, K_HASTANO,\n                HASTALIK_DIYABET, HASTALIK_HEPATIT, HASTALIK_HIV, HASTALIK_COVID, HASTALIK_DIGER,\n                SIGORTA_POLICENO, SGK_KURUM, SGK_SOSYALGUVNO,\n                IPTAL,\n                -- KVKK ve Onam Bilgileri\n                K.KVKKabulEdiyorum, K.KVKKabulEtmiyorum, K.KVKK_IYSOnayID, \n                K.HukukiTemsilci_Isim, K.HukukiTemsilci_YakinlikDerecesi,\n                K.BilgilendirmeTalebi_Sms, K.BilgilendirmeTalebi_Email, K.BilgilendirmeTalebi_Telefon as BilgilendirmeTalebi_Arama,\n                K.eIYS_ETKSmsIzniOnayTarihi, K.eIYS_ETKEmailIzniOnayTarihi, K.eIYS_ETKAramaIzniOnayTarihi,\n                K.SonIslemTarihi as ConsentDate\n            FROM HST_ANADOSYA P\n            LEFT JOIN Hst_Anadosya_GizlilikOnamFormu K ON P.HASTANO = K.HastaNo\n            ORDER BY P.HASTANO\n        ")).recordset.map((e=>{const n=[];e.HASTALIK_DIYABET&&n.push("Diyabet"),e.HASTALIK_HEPATIT&&n.push("Hepatit"),e.HASTALIK_HIV&&"H"!==e.HASTALIK_HIV&&n.push("HIV"),e.HASTALIK_COVID&&n.push("COVID"),e.HASTALIK_DIGER&&n.push(e.HASTALIK_DIGER);const i=[e.EV_ADRES1,e.EV_ADRES2,e.EV_ADRES_SEMT].filter((e=>e&&e.trim())).join(", ");return{legacy_id:e.HASTANO,name:`${e.AD||""} ${e.SOYAD||""}`.trim()||`Hasta ${e.HASTANO}`,tc_no:e.KIMLIKNO||"",phone:e.EV_MOBIL||e.EV_TELEFON||"",email:e.EV_EMAIL||null,birth_date:e.DGMTRH?new Date(e.DGMTRH).toISOString().split("T")[0]:null,gender:"E"===e.CINSIYET?"M":"K"===e.CINSIYET?"F":"U",blood_type:e.KANGRUBU||null,address:i||null,city:e.EV_ADRES_IL||null,district:e.EV_ADRES_ILCE||null,notes:e.NOTLAR||null,status:e.IPTAL?0:1,medical_info:{allergies:{drug:e.ILACALERJISI||null,substance:e.MADDEALERJISI||null},chronic_diseases:n,warnings:e.TIBBIUYARI||null,blood_type_details:e.KANGRUBU||null,disabilities:null},work_details:{company_name:e.IS_ADI||null,role:e.IS_GOREVI||null,phone:e.IS_TELEFON||null,address:[e.IS_ADRES1,e.IS_ADRES2,e.IS_ADRES_SEMT,e.IS_ADRES_ILCE,e.IS_ADRES_IL].filter(Boolean).join(", ")||null,email:e.IS_EMAIL||null,profession:e.MESLEK||null},identity_details:{father_name:e.BABAADI||null,mother_name:e.ANNEADI||null,birth_place:e.DOGUMYERI||null,nationality:e.NK_UYRUGU||"TR",marital_status:e.NK_MEDENIHALI||null,spouse_name:e.ESININADI||null,tax_no:e.VERGINO||null,population_registry:{province_code:e.NK_ILKODU||null,district_code:e.NK_ILCEKODU||null,volume_no:e.NK_CILTNO||null,family_order_no:e.NK_AILENO||null,order_no:e.NK_SIRANO||null}},insurance_info:{policies:e.SIGORTA_POLICENO?[{policy_no:e.SIGORTA_POLICENO,institution:e.SGK_KURUM}]:[],sgk_status:e.SGK_SIGORTALIDURUMU||null,social_security_no:e.SGK_SOSYALGUVNO||null},legacy_metadata:{archive_no:e.ARSIVNO||null,legacy_patient_no:e.HASTANO,k_hastano:e.K_HASTANO||null,migration_notes:"Migrated from Intermedia"},legal_consents:{kvkk:{is_accepted:!!e.KVKKabulEdiyorum,is_rejected:!!e.KVKKabulEtmiyorum,accepted_at:e.ConsentDate||null,legal_representative:e.HukukiTemsilci_Isim?{name:e.HukukiTemsilci_Isim,degree:e.HukukiTemsilci_YakinlikDerecesi}:null,iys_id:e.KVKK_IYSOnayID||null},etk:{sms:{allowed:!!e.BilgilendirmeTalebi_Sms,date:e.eIYS_ETKSmsIzniOnayTarihi||null},email:{allowed:!!e.BilgilendirmeTalebi_Email,date:e.eIYS_ETKEmailIzniOnayTarihi||null},call:{allowed:!!e.BilgilendirmeTalebi_Arama,date:e.eIYS_ETKAramaIzniOnayTarihi||null}}}}}));return this.stats.patients=e.length,e}async extractAppointments(){const e=(await this.mssqlPool.request().query("\n            SELECT \n                GELISNO,\n                PROTOKOLNO,\n                HASTANO,\n                DOKTOR_ID,\n                TARIH,\n                IPTAL\n            FROM HST_GELISLER\n            ORDER BY GELISNO\n        ")).recordset.map((e=>({legacy_visit_id:e.GELISNO,protocol_no:e.PROTOKOLNO||null,patient_legacy_id:e.HASTANO,doctor_legacy_id:e.DOKTOR_ID,appointment_date:e.TARIH?new Date(e.TARIH).toISOString().slice(0,19).replace("T"," "):null,status:e.IPTAL?"cancelled":"completed"})));return this.stats.appointments=e.length,e}async extractAppointmentItems(){const e=(await this.mssqlPool.request().query("\n            SELECT \n                i.RECORD_ID,\n                i.GELISNO,\n                i.ISLEMNO,\n                i.FIYAT,\n                i.ADET,\n                i.YAPAN,\n                t.ACIKLAMA as ISLEM_ADI\n            FROM HST_ISLEMLER i\n            LEFT JOIN TETKIK t ON i.ISLEMNO = t.KOD\n            ORDER BY i.GELISNO, i.RECORD_ID\n        ")).recordset.map((e=>({appointment_legacy_id:e.GELISNO,service_legacy_code:String(e.ISLEMNO),item_name:e.ISLEM_ADI||`İşlem ${e.ISLEMNO}`,quantity:e.ADET||1,unit_price:parseFloat(e.FIYAT)||0,total_price:(parseFloat(e.FIYAT)||0)*(e.ADET||1),performer_legacy_id:e.YAPAN})));return this.stats.items=e.length,e}async extractExaminations(){const e=(await this.mssqlPool.request().query("\n            SELECT \n                t.GELISNO,\n                et.SIKAYETLER,\n                et.HIKAYESI,\n                et.BULGULAR,\n                et.TESHIS,\n                et.TEDAVI,\n                et.SONUC,\n                et.TARIH\n            FROM HST_TIBBI_EPIKRIZ_TAKIP et\n            INNER JOIN HST_TIBBI_EPIKRIZ e ON et.EPIKRIZ_ID = e.ID\n            INNER JOIN HST_TIBBI t ON e.TIBBIDOSYA_ID = t.RECORD_ID\n            ORDER BY et.EPIKRIZ_ID\n        ")).recordset.map((e=>({legacy_visit_id:e.GELISNO,complaint:e.SIKAYETLER||null,story:e.HIKAYESI||null,bulgular:e.BULGULAR||null,diagnosis:e.TESHIS||null,treatment:e.TEDAVI||null,result_note:e.SONUC||null,created_at:e.TARIH?new Date(e.TARIH).toISOString().slice(0,19).replace("T"," "):null})));return this.stats.examinations=e.length,e}async extractAll(){await this.connect();try{const e={clinic_id:1,extracted_at:(new Date).toISOString(),users:await this.extractUsers(),services:await this.extractServices(),patients:await this.extractPatients(),appointments:await this.extractAppointments(),appointment_items:await this.extractAppointmentItems(),examinations:await this.extractExaminations()},n=require("fs"),i=require("path").resolve(__dirname,"..","data","migration_data.json");return n.writeFileSync(i,JSON.stringify(e,null,2)),e}finally{await this.disconnect()}}}const migrator=new DataMigrator;migrator.extractAll().catch((e=>{process.exit(1)}));